package com.bank.ring;

import java.math.BigDecimal;

// Reusable slot object — mutated in place, never re-allocated per event.
public class OrderEvent {
    private String accountId;
    private String symbol;
    private BigDecimal amount;

    public void set(String accountId, String symbol, BigDecimal amount) {
        this.accountId = accountId; this.symbol = symbol; this.amount = amount;
    }
    public String getAccountId() { return accountId; }
    public String getSymbol() { return symbol; }
    public BigDecimal getAmount() { return amount; }
}
