package com.bank.ring;

import java.math.BigDecimal;
import java.util.concurrent.atomic.AtomicLong;

// Educational single-writer ring buffer mirroring the Disruptor's ideas:
// power-of-two slots, reused OrderEvent objects, sequence-based coordination.
public class OrderRingBuffer {
    private final OrderEvent[] slots;
    private final int mask;                       // size - 1, for bitmask indexing
    private final AtomicLong cursor = new AtomicLong(-1);  // last PUBLISHED sequence
    private long consumerSeq = -1;                // consumer's own sequence

    public OrderRingBuffer(int size) {
        if (Integer.bitCount(size) != 1) throw new IllegalArgumentException("size must be power of two");
        this.slots = new OrderEvent[size];
        this.mask = size - 1;
        for (int i = 0; i < size; i++) slots[i] = new OrderEvent();  // pre-allocate ALL slots
    }

    // Producer (single writer): claim next sequence, write in place, publish.
    public void publish(String accountId, String symbol, BigDecimal amount) {
        long next = cursor.get() + 1;             // single-writer: no CAS loop needed here
        OrderEvent slot = slots[(int) (next & mask)];
        slot.set(accountId, symbol, amount);      // mutate reused slot — no allocation
        cursor.set(next);                         // publish: now visible to consumer
    }

    // Consumer: follow the barrier (cursor) up to the highest available sequence.
    public int drain(java.util.function.Consumer<OrderEvent> handler) {
        long available = cursor.get();            // sequence barrier: how far can I read?
        int processed = 0;
        while (consumerSeq < available) {
            consumerSeq++;
            handler.accept(slots[(int) (consumerSeq & mask)]);
            processed++;
        }
        return processed;
    }
}
