package com.bank.ring;

import java.math.BigDecimal;
import java.util.logging.Logger;

public class RingBufferDemo {
    private static final Logger log = Logger.getLogger(RingBufferDemo.class.getName());

    public static void main(String[] args) {
        OrderRingBuffer ring = new OrderRingBuffer(1024);   // power of two

        // Single writer publishes orders (no locks on the data path).
        ring.publish("SAV2001", "RELIANCE", new BigDecimal("245050.00"));
        ring.publish("CUR3001", "TCS",      new BigDecimal("180000.00"));
        ring.publish("SAV2001", "INFY",     new BigDecimal("95000.00"));

        // Consumer drains in published order via the sequence barrier.
        int count = ring.drain(e ->
            log.info(() -> "Matched order " + e.getAccountId() + " " + e.getSymbol() + " " + e.getAmount()));
        log.info(() -> "Processed " + count + " orders lock-free");
    }
}
