package com.bank.ring;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import static org.junit.jupiter.api.Assertions.assertEquals;

class OrderRingBufferTest {
    @Test
    void publishesAndDrainsInOrder() {
        OrderRingBuffer ring = new OrderRingBuffer(8);
        ring.publish("SAV2001", "RELIANCE", new BigDecimal("100"));
        ring.publish("CUR3001", "TCS", new BigDecimal("200"));

        List<String> seen = new ArrayList<>();
        int n = ring.drain(e -> seen.add(e.getSymbol()));
        assertEquals(2, n);
        assertEquals(List.of("RELIANCE", "TCS"), seen);   // FIFO order preserved
    }
}
